{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic is created without a kms_key_name, meaning it relies on Google-managed encryption keys. For production workloads handling sensitive data like insurance claims, using Customer-Managed Encryption Keys (CMEK) via Cloud KMS provides better control over key rotation and access."
    }
  ],
  "patched_code": "resource "google_pubsub_topic" "notification_queue" {
  name = "insurance-claims-processing-platform-pubsub-notifications"
  labels = {
    environment = "production"
    component   = "notifications"
  }

  # CKV_GCP_83: Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)
  # Replace the placeholder below with the actual URI of your Cloud KMS CryptoKey.
  # Example: "projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key"
  kms_key_name = var.pubsub_kms_key_name
}

variable "pubsub_kms_key_name" {
  description = "The resource name for the Cloud KMS cryptoKey to use with this topic."
  type        = string
}",
  "fix_summary": "Added a `kms_key_name` attribute to the `google_pubsub_topic` resource to enable Customer-Managed Encryption Keys (CMEK). Introduced a variable `pubsub_kms_key_name` to allow flexible configuration of the KMS key URI without hardcoding secrets or specific project IDs in the module."
}
